import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { AlertController, LoadingController, ToastController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { VehicleProfile, VehicleProfileStore } from '../vehicle-profile/vehicle-profile.store';

interface DynamicCompressionResult {
  cylinderVolumeCc: number;
  clearanceVolumeCc: number;
  pistonPositionAtIvcMm: number;
  effectiveStrokeMm: number;
  effectiveDisplacementCc: number;
  dynamicCompressionRatio: number;
}

@Component({
  selector: 'app-dynamic-compression',
  templateUrl: './dynamic-compression.component.html',
  styleUrls: ['./dynamic-compression.component.scss'],
})
export class DynamicCompressionComponent implements OnInit {

  isShow = false;
  isCheck = true;
  profiles: VehicleProfile[] = [];
  selectedProfileId = '';
  profileNotice = '';
  private loadedProfileUpdatedAt = '';
  form: FormGroup;
  result: DynamicCompressionResult | null = null;

  constructor(private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private courseService: CourseService,
    private siteService: SliderService) {

    this.isShow = false;
    this.check();
  }

  ionViewWillEnter(): void {
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active && this.form && (active.id !== this.selectedProfileId ||
      active.updatedAt !== this.loadedProfileUpdatedAt)) {
      this.applyProfile(active.id);
    }
  }

  applyProfile(id: string): void {
    const profile = this.profiles.find(item => item.id === id);
    if (!profile || !this.form) { return; }
    const values = VehicleProfileStore.toolValues(profile, 'dynamic-compression');
    let applied = 0;
    Object.keys(values).forEach(key => {
      const control = this.form.get(key);
      if (!control) { return; }
      const previous = control.value;
      control.setValue(values[key], { emitEvent: false });
      if (control.invalid) { control.setValue(previous, { emitEvent: false }); }
      else { applied++; }
    });

    this.form.updateValueAndValidity();
    this.profileNotice = `${applied} مقدار از پروفایل اعمال شد؛ سایر ورودی‌ها پیش‌فرض ابزارند.`;
    this.selectedProfileId = id;
    this.loadedProfileUpdatedAt = profile.updatedAt;
    try { VehicleProfileStore.select(id); } catch { /* Local storage may be disabled. */ }
    this.calculate();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(37).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;
                              this.isShow = true;
                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
              this.isShow = true;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit(): void {
    this.form = this.fb.group({
      boreMm: [78.5, [Validators.required, Validators.min(1)]],
      strokeMm: [82, [Validators.required, Validators.min(1)]],
      rodLengthMm: [137, [Validators.required, Validators.min(1)]],
      staticCompressionRatio: [10.5, [Validators.required, Validators.min(1.01)]],
      intakeValveClosingAbdc: [49.5, [Validators.required, Validators.min(0), Validators.max(180)]],
    });
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active) { this.applyProfile(active.id); }

    this.form.valueChanges.subscribe(() => this.calculate());
    this.calculate();
  }

  calculate(): void {
    if (this.form.invalid) {
      this.result = null;
      return;
    }

    const value = this.form.getRawValue();
    const boreMm = Number(value.boreMm);
    const strokeMm = Number(value.strokeMm);
    const rodLengthMm = Number(value.rodLengthMm);
    const staticCompressionRatio = Number(value.staticCompressionRatio);
    const intakeValveClosingAbdc = Number(value.intakeValveClosingAbdc);
    const crankRadiusMm = strokeMm / 2;

    if (rodLengthMm <= crankRadiusMm) {
      this.result = null;
      return;
    }

    // Crank angle is measured from TDC. IVC supplied as degrees ABDC is
    // therefore 180 + IVC. The result is piston travel from TDC, which is
    // the effective compression stroke remaining after the intake closes.
    const crankAngleRad = (180 + intakeValveClosingAbdc) * Math.PI / 180;
    const pistonPositionAtIvcMm = crankRadiusMm * (1 - Math.cos(crankAngleRad))
      + rodLengthMm
      - Math.sqrt(Math.pow(rodLengthMm, 2) - Math.pow(crankRadiusMm * Math.sin(crankAngleRad), 2));

    const cylinderVolumeCc = Math.PI / 4 * Math.pow(boreMm / 10, 2) * (strokeMm / 10);
    const clearanceVolumeCc = cylinderVolumeCc / (staticCompressionRatio - 1);
    const effectiveStrokeMm = Math.max(0, Math.min(strokeMm, pistonPositionAtIvcMm));
    const effectiveDisplacementCc = cylinderVolumeCc * (effectiveStrokeMm / strokeMm);
    const dynamicCompressionRatio = (effectiveDisplacementCc + clearanceVolumeCc) / clearanceVolumeCc;

    this.result = {
      cylinderVolumeCc: this.round(cylinderVolumeCc, 2),
      clearanceVolumeCc: this.round(clearanceVolumeCc, 2),
      pistonPositionAtIvcMm: this.round(pistonPositionAtIvcMm, 2),
      effectiveStrokeMm: this.round(effectiveStrokeMm, 2),
      effectiveDisplacementCc: this.round(effectiveDisplacementCc, 2),
      dynamicCompressionRatio: this.round(dynamicCompressionRatio, 2),
    };
  }

  reset(): void {
    this.form.reset({
      boreMm: 78.5,
      strokeMm: 82,
      rodLengthMm: 137,
      staticCompressionRatio: 10.5,
      intakeValveClosingAbdc: 49.5,
    });
  }

  get recommendation(): string {
    const dcr = this.result?.dynamicCompressionRatio;
    if (!dcr) { return 'برای نمایش نتیجه، تمام ورودی‌ها را با مقادیر معتبر وارد کنید.'; }
    if (dcr < 7) { return 'تراکم دینامیک پایین است؛ پاسخ دور پایین و راندمان ممکن است ضعیف باشد.'; }
    if (dcr <= 8.5) { return 'محدوده‌ی محافظه‌کارانه برای بسیاری از موتورهای خیابانی بنزینی تنفس طبیعی.'; }
    if (dcr <= 9) { return 'محدوده‌ی پرفورمنس؛ کیفیت سوخت، دمای هوا و تنظیم جرقه را دقیق بررسی کنید.'; }
    return 'تراکم دینامیک بالاست؛ فقط با سوخت و کالیبراسیون مناسب استفاده شود.';
  }

  get recommendationColor(): string {
    const dcr = this.result?.dynamicCompressionRatio;
    if (!dcr || dcr < 7) { return 'warning'; }
    if (dcr <= 8.5) { return 'success'; }
    return dcr <= 9 ? 'warning' : 'danger';
  }

  async onInfo(type: string): Promise<void> {
    const messages: Record<string, string> = {
      bore: 'قطر داخلی نهایی هر سیلندر پس از تراش یا هونینگ، برحسب میلی‌متر.',
      stroke: 'کورس میل‌لنگ؛ فاصله حرکت پیستون از نقطه مرگ بالا تا پایین، برحسب میلی‌متر.',
      rod: 'طول شاتون از مرکز پین پیستون تا مرکز ژورنال میل‌لنگ. این مقدار روی کورس مؤثر اثر دارد.',
      compression: 'نسبت تراکم استاتیک واقعی موتور. برای دقت، آن را ابتدا با ابزار Compression و Quench محاسبه کنید.',
      ivc: 'زاویه بسته شدن سوپاپ هوا پس از BDC. مقدار واقعی میل‌سوپاپ و مبنای اندازه‌گیری آن را وارد کنید؛ IVC دیرتر، تراکم دینامیک را کاهش می‌دهد.',
    };
    await this.presentInfo(messages[type] || 'توضیحی برای این پارامتر موجود نیست.');
  }

  private async presentInfo(message: string): Promise<void> {
    const alert = await this.alertController.create({ cssClass: 'main-alert', header: 'توضیحات', message, buttons: ['بستن'] });
    await alert.present();
  }

  private round(value: number, decimals: number): number {
    const factor = Math.pow(10, decimals);
    return Math.round((value + Number.EPSILON) * factor) / factor;
  }
}
