import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';

import { DynamicCompressionComponent } from './dynamic-compression.component';

const routes: Routes = [
  {
    path: '',
    component: DynamicCompressionComponent,
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class DynamicCompressionRoutingModule {}
